# Report narration-only rhythm after edits.
for fn in ['082-다섯-개의-문-v1.md','084-학원-헌장-0.1-v1.md','093-중앙키-v1.md','099-살아남은-학교의-청구서-v1.md']:
    p=ROOT/fn; t=p.read_text(encoding='utf-8'); pos=t.find('# 제'); body=t[pos:]
    ps=[x.strip() for x in re.split(r'\n\s*\n',body) if x.strip()]
    narr=[]; run=maxrun=0
    for q in ps:
        if q.startswith('#') or q=='* * *' or (q.startswith('[') and q.endswith(']')) or q.startswith(('“','"')):
            run=0; continue
        narr.append(q)
        if len(q)<=24: run+=1; maxrun=max(maxrun,run)
        else: run=0
    short=sum(len(q)<=24 for q in narr)
    med=statistics.median([len(q) for q in narr]) if narr else 0
    print(f'{fn}: narr_short={short}/{len(narr)} ratio={short/max(len(narr),1):.3f} maxrun={maxrun} median={med}')
